package test;
import org.eclipse.core.resources.IResource;
import org.eclipse.jdt.core.IPackageFragmentRoot;
import org.eclipse.jdt.core.JavaModelException;

public class MyContentProvider {
    public void checkResource(Object element) throws JavaModelException {
        if (element instanceof IPackageFragmentRoot) {
            IPackageFragmentRoot root = (IPackageFragmentRoot) element;
            IResource resource = root.getResource();
            if (resource != null) { // This line is the target
                System.out.println("Resource exists: " + resource.getName());
            }
        }
    }
}

afterExample:
package test;
import org.eclipse.core.resources.IResource;
import org.eclipse.jdt.core.IPackageFragmentRoot;
import org.eclipse.jdt.core.JavaModelException;

public class MyContentProvider {
    public void checkResource(Object element) throws JavaModelException {
        if (element instanceof IPackageFragmentRoot) {
            IPackageFragmentRoot root = (IPackageFragmentRoot) element;
            IResource resource = root.getResource();
            if (resource != null && !resource.exists()) { // This line is the target
                System.out.println("Resource exists: " + resource.getName());
            }
        }
    }
}

